  nav.innerHTML = '<button id="rotateMode" aria-pressed="true">Döndür</button><button id="panMode" aria-pressed="false">Kaydır</button>';
  document.querySelector(".viewer-toolbar").append(nav);
  const mode = (pan) => {
    cancelMotion();
    controls2.mouseButtons.LEFT = pan ? THREE.MOUSE.PAN : THREE.MOUSE.ROTATE;
    controls2.touches.ONE = pan ? THREE.TOUCH.PAN : THREE.TOUCH.ROTATE;
    mount2.dataset.navigation = pan ? "pan" : "rotate";
    nav.querySelector("#panMode").setAttribute("aria-pressed", String(pan));
    nav.querySelector("#rotateMode").setAttribute("aria-pressed", String(!pan));
  };
  nav.querySelector("#panMode").onclick = () => mode(true);
  nav.querySelector("#rotateMode").onclick = () => mode(false);
  const shift = (direction) => {
    cancelMotion();
    const height = 2 * camera2.position.distanceTo(controls2.target) * Math.tan(camera2.fov * Math.PI / 360);
    const delta = new THREE.Vector3(0, direction * height * 0.22, 0);
    camera2.position.add(delta);
    controls2.target.add(delta);
    controls2.update();
    requestRender2();
  };
  const buttons = document.createElement("div");
  buttons.className = "vertical-pan";
  buttons.innerHTML = '<button id="panUp" aria-label="Görünümü başa doğru kaydır">↑</button><button id="panDown" aria-label="Görünümü ayağa doğru kaydır">↓</button>';
  document.querySelector(".view-controls").append(buttons);
  buttons.querySelector("#panUp").onclick = () => shift(1);
  buttons.querySelector("#panDown").onclick = () => shift(-1);
  const hint = document.createElement("p");
  hint.className = "navigation-hint";
  hint.textContent = "Kaydır modunda sürükleyerek başa veya ayaklara git. İki parmakla yakınlaştır ve kaydır.";
  document.querySelector(".gesture")?.replaceWith(hint);
