function decorateDetails() {
  const content = $("#detailContent");
  if (content.querySelector(".detail-jumps")) return;
  const nav = document.createElement("nav");
  nav.className = "detail-jumps";
  nav.setAttribute("role", "tablist");
  nav.setAttribute("aria-label", "Yapı bilgisi");
  for (const n of [...content.children]) {
    if (n.matches(".detail-block,.takeaway,.related-structures,.detail-sources,.parent-note,.content-scope")) n.dataset.detailView = "general";
    if (n.matches('[data-explanation="03"],.anatomy-facts,.advanced-card,#connectionInfo')) n.dataset.detailView = "relations";
    if (n.matches('[data-explanation="04"],.clinical-study')) n.dataset.detailView = "clinical";
    if (n.matches(".personal-card")) n.dataset.detailView = "notes";
  }
  for (const [key, label] of [["general", "Genel"], ["relations", "İlişkiler"], ["clinical", "Klinik"], ["notes", "Notlar"]]) {
    const b = document.createElement("button");
    b.type = "button";
    b.setAttribute("role", "tab");
    b.dataset.detailTab = key;
    b.textContent = label;
    b.onclick = () => {
      content.dataset.detailView = key;
      for (const x of nav.children) {
        const on = x === b;
        x.setAttribute("aria-selected", String(on));
        x.tabIndex = on ? 0 : -1;
      }
      if (key === "relations") document.dispatchEvent(new CustomEvent("atlas-inspection-mode", { detail: "connections" }));
    };
    nav.append(b);
  }
  nav.onkeydown = (e) => {
    const bs = [...nav.children], i = bs.indexOf(document.activeElement);
    if (i < 0 || !["ArrowRight", "ArrowLeft"].includes(e.key)) return;
    e.preventDefault();
    const b = bs[(i + (e.key === "ArrowRight" ? 1 : bs.length - 1)) % bs.length];
    b.click();
    b.focus();
  };
  content.querySelector(".detail-actions")?.after(nav);
  nav.firstElementChild.click();
}

