// dist/motion.js
init_three_module();
init_OrbitControls();
function openMotion(objects2) {
  const dialog = document.querySelector("#motionDialog"), mount2 = document.querySelector("#motionCanvas");
  const humerus = [...objects2.values()].find((o) => /^Humerus\.l\./.test(o.userData.record.name));
  if (!humerus) throw Error("Erkek referansındaki kol kemikleri yüklenmeli.");
  dialog.showModal();
  mount2.replaceChildren();
  const renderer2 = new WebGLRenderer({ antialias: true, alpha: true });
  renderer2.setPixelRatio(Math.min(devicePixelRatio, 1.5));
  renderer2.setSize(mount2.clientWidth, mount2.clientHeight);
  renderer2.toneMapping = ACESFilmicToneMapping;
  mount2.appendChild(renderer2.domElement);
  const scene2 = new Scene(), camera2 = new PerspectiveCamera(40, mount2.clientWidth / mount2.clientHeight, 0.01, 10);
  scene2.add(new HemisphereLight(16772832, 3425878, 2));
  const light = new DirectionalLight(16777215, 2);
  light.position.set(1, 2, 3);
  scene2.add(light);
  const hbox = new Box3().setFromObject(humerus), hc = hbox.getCenter(new Vector3()), pivot = new Vector3(hc.x, hbox.min.y + 0.015, hc.z);
  const lower3 = new Group();
  lower3.position.copy(pivot);
  scene2.add(lower3);
  const muscles = [];
  const resources = [];
  for (const o of objects2.values()) {
    const r = o.userData.record;
    if (!/\.l\./.test(r.name) || r.sex !== "male") continue;
    const box = new Box3().setFromObject(o), c = box.getCenter(new Vector3());
    const bone = r.layer === "skeleton" && (o === humerus || c.x > 0.09 && c.y < pivot.y + 0.05 && c.y > 0.52);
    const muscle = r.layer === "muscular" && /biceps brachii/i.test(r.name);
    if (!bone && !muscle) continue;
    const geometry = o.geometry.clone();
    geometry.applyMatrix4(o.matrixWorld);
    const material = new MeshStandardMaterial({ color: muscle ? "#a65049" : "#ded1b7", roughness: 0.55 });
    const copy = new Mesh(geometry, material);
    resources.push(copy);
    if (bone && o !== humerus) {
      geometry.translate(-pivot.x, -pivot.y, -pivot.z);
      lower3.add(copy);
    } else {
      scene2.add(copy);
      if (muscle) muscles.push({ mesh: copy, base: geometry.attributes.position.array.slice() });
    }
  }
  const controls2 = new OrbitControls(camera2, renderer2.domElement);
  controls2.target.set(hc.x, hc.y - 0.05, hc.z + 0.08);
  camera2.position.set(hc.x + 0.8, hc.y + 0.1, hc.z + 1.1);
  controls2.update();
  let animation = 0, playing = false, start = 0;
  function draw(angle) {
    const rad = angle * Math.PI / 180;
    lower3.rotation.x = -rad;
    const insertion = pivot.clone().add(new Vector3(0, -0.07, 0));
    const moved = insertion.clone().sub(pivot).applyAxisAngle(new Vector3(1, 0, 0), -rad).add(pivot);
    const delta = moved.sub(insertion);
    for (const { mesh, base: base3 } of muscles) {
      const p = mesh.geometry.attributes.position;
      for (let i = 0; i < p.count; i++) {
        const y = base3[i * 3 + 1], weight = MathUtils.clamp((hbox.max.y - y) / (hbox.max.y - pivot.y + 0.07), 0, 1);
        p.setXYZ(i, base3[i * 3] + delta.x * weight, y + delta.y * weight, base3[i * 3 + 2] + delta.z * weight);
      }
      p.needsUpdate = true;
      mesh.geometry.computeVertexNormals();
    }
    document.querySelector("#motionAngleValue").textContent = Math.round(angle) + "°";
    renderer2.render(scene2, camera2);
  }
  const slider = document.querySelector("#motionAngle"), play = document.querySelector("#motionPlay");
  slider.value = 0;
  draw(0);
  controls2.addEventListener("change", () => draw(+slider.value));
  slider.oninput = () => {
    playing = false;
    cancelAnimationFrame(animation);
    play.textContent = "Oynat";
    draw(+slider.value);
  };
  function tick(time) {
    if (!playing) return;
    if (!start) start = time;
    const angle = 55 - 55 * Math.cos((time - start) / 1800);
    slider.value = angle;
    draw(angle);
    animation = requestAnimationFrame(tick);
  }
  play.onclick = () => {
    playing = !playing;
    play.textContent = playing ? "Duraklat" : "Oynat";
    if (playing) {
      start = 0;
      animation = requestAnimationFrame(tick);
    } else cancelAnimationFrame(animation);
  };
  const observer = new ResizeObserver(() => {
    camera2.aspect = mount2.clientWidth / mount2.clientHeight;
    camera2.updateProjectionMatrix();
    renderer2.setSize(mount2.clientWidth, mount2.clientHeight);
    draw(+slider.value);
  });
  observer.observe(mount2);
  dialog.addEventListener("close", () => {
    playing = false;
    cancelAnimationFrame(animation);
    observer.disconnect();
    controls2.dispose();
    for (const o of resources) {
      o.geometry.dispose();
      o.material.dispose();
    }
    renderer2.dispose();
    mount2.replaceChildren();
  }, { once: true });
}

