    catalog.forEach((r) => r.search = searchText(r.name, r.layer));
    const coverage = { specific: 0, parent: 0, group: 0, general: 0 };
    catalog.forEach((r) => coverage[clinicalProfile(r).scope]++);
    const latin = catalog.filter((r) => terminologyFor(r)).length;
