  if (axis === "oblique") {
    const yaw = Number($3("#cutYaw").value) * Math.PI / 180, pitch = Number($3("#cutPitch").value) * Math.PI / 180;
    n.set(Math.sin(yaw) * Math.cos(pitch), -Math.sin(pitch), -Math.cos(yaw) * Math.cos(pitch));
  }
  const { low, high } = cutRange(n);
  $3("#cutPosition").value = 100 * (high - n.dot(point)) / Math.max(1e-4, high - low);
