async function switchSex(value) {
  if (course?.active) course.close();
  if (!["male", "female"].includes(value)) throw Error("Geçersiz referans");
  const previous = { sex, active: [...active], camera: camera.position.clone(), target: controls.target.clone() };
  let success = true;
  relationTicket++;
  relationRoles.clear();
  relationRoot = null;
  cameraMotion = null;
  document.body.classList.remove("detail-expanded");
  $3("#expandDetail").setAttribute("aria-expanded", "false");
  $3("#expandDetail").textContent = "Tam oku";
  sex = value;
  $3("#sexModel").value = value;
  selected = null;
  isolated = false;
  $3("#details").classList.remove("has-selection");
  hidden.clear();
  undoStack.length = 0;
  $3("#details").classList.remove("open");
  $3("#selectionLabel").hidden = true;
  $3("#detailContent").innerHTML = '<div class="empty-symbol">◎</div><h2>Bir yapı seç.</h2><p>Yeni referansta bir parçaya dokun veya adıyla ara.</p>';
  active.clear();
  for (const k of sex === "female" ? ["surface", "skeleton", "visceral"] : ["skeleton", "muscular"]) active.add(k);
  reset();
  renderLayers();
  $3("#sexBadge").textContent = sex === "female" ? "Kadın · HRA" : "Erkek · Z-Anatomy";
  $3("#modelScope").textContent = sex === "female" ? "1.032 parça · 76 ek alt ekstremite kası. Ek kas yerleşimi yaklaşık; kafatası ve üst kol kasları eksik." : "2.338 parça · Erkek referansı";
  $3("#offlineStatus").textContent = "Seçili referansı bu cihazda saklayabilirsin.";
  $3("#search").value = "";
  search();
  $3("#sexModel").disabled = true;
  $3("#loading").hidden = false;
  $3("#loadText").textContent = sex === "female" ? "Kadın referansı yükleniyor…" : "Erkek referansı yükleniyor…";
  try {
    await Promise.all([...active].map(loadLayer));
  } catch (e) {
    success = false;
    sex = previous.sex;
    $3("#sexModel").value = sex;
    active.clear();
    previous.active.forEach((k) => active.add(k));
    cameraMotion = null;
    camera.position.copy(previous.camera);
    controls.target.copy(previous.target);
    controls.update();
    $3("#sexBadge").textContent = sex === "female" ? "Kadın · HRA" : "Erkek · Z-Anatomy";
    $3("#modelScope").textContent = "Önceki referans korundu. Diğer referansı tekrar seçerek yeniden deneyebilirsin.";
    renderLayers();
    toast("Referans yüklenemedi. Önceki model korundu; tekrar deneyebilirsin.");
  } finally {
    $3("#sexModel").disabled = false;
    $3("#loading").hidden = true;
    scene.updateMatrixWorld(true);
    organMotion.rebuild(objects, sex);
    refresh();
  }
  return success;
}
var quizQueue = [];
var quizIndex = 0;
var quizScore = 0;
var quizAnswered = false;
var quizWrong = [];
function savedMistakes() {
  try {
    const ids = JSON.parse(localStorage.getItem("anatomi-mistakes") || "[]");
    return Array.isArray(ids) ? ids.filter((x) => typeof x === "string") : [];
  } catch {
    return [];
  }
}
function saveMistakes(ids) {
  try {
    localStorage.setItem("anatomi-mistakes", JSON.stringify([...new Set(ids)]));
  } catch {
  }
}
function startQuiz(repeat = false) {
  const wrong = savedMistakes();
  quizQueue = questionSet(sex, repeat ? wrong : []);
  if (repeat && !wrong.length) {
    toast("Tekrar edilecek yanlış cevabın yok.");
    return;
  }
  if (!quizQueue.length) {
    toast("Bu referans için tekrar edilecek soru yok.");
    return;
  }
  quizIndex = 0;
  quizScore = 0;
  quizWrong = [];
  if (!$3("#quizDialog").open) $3("#quizDialog").showModal();
  renderQuiz();
}
function renderQuiz() {
  quizAnswered = false;
  const q = quizQueue[quizIndex];
  if (!q) {
    $3("#quizContent").innerHTML = '<div class="quiz-result"><b>' + quizScore + " / " + quizQueue.length + " doğru</b><p>" + quizWrong.length + ' soruyu tekrar çalışabilirsin. Yanlışlar yalnızca bu cihazda saklanır.</p></div><div class="quiz-buttons"><button id="quizRestart">Yeni tur</button><button id="quizRepeat">Yanlışları tekrar et</button></div>';
    $3("#quizRestart").onclick = () => startQuiz();
    $3("#quizRepeat").onclick = () => startQuiz(true);
    return;
  }
  $3("#quizContent").innerHTML = '<p class="quiz-progress">Soru ' + (quizIndex + 1) + " / " + quizQueue.length + " · " + (sex === "female" ? "Kadın" : "Erkek") + " referansı</p><h3>" + esc2(q.q) + "</h3>" + q.options.map((s, i) => '<button class="quiz-option" data-answer="' + i + '">' + esc2(s) + "</button>").join("") + '<div id="quizFeedback" aria-live="polite"></div>';
  document.querySelectorAll("[data-answer]").forEach((b) => b.onclick = () => {
    if (quizAnswered) return;
    quizAnswered = true;
    const index = Number(b.dataset.answer), result = answerQuestion(q, index);
    let mistakes = savedMistakes();
    if (result.correct) {
      quizScore++;
      mistakes = mistakes.filter((id) => id !== q.id);
    } else {
      quizWrong.push(q.id);
      mistakes.push(q.id);
    }
    saveMistakes(mistakes);
    document.querySelectorAll("[data-answer]").forEach((x) => {
      x.disabled = true;
      if (Number(x.dataset.answer) === q.correct) x.classList.add("correct");
    });
    if (!result.correct) b.classList.add("wrong");
    $3("#quizFeedback").innerHTML = '<div class="quiz-result">' + (result.correct ? "Doğru. " : "Doğru yanıt: " + esc2(q.options[q.correct]) + ". ") + esc2(result.explanation) + '</div><div class="quiz-buttons"><button id="quizModel">Modelde incele ↗</button><button id="quizNext">' + (quizIndex + 1 === quizQueue.length ? "Sonuçlar" : "Sonraki soru") + "</button></div>";
    $3("#quizNext").onclick = () => {
      quizIndex++;
      renderQuiz();
    };
    $3("#quizModel").onclick = async () => {
      const r = matches(q.target).find((r2) => isExactTopic(r2.name, topicFor(r2.name))) || matches(q.target)[0];
      if (!r) {
        toast("Bu yapı seçili referansta ayrı modellenmemiş.");
        return;
      }
      $3("#quizDialog").close();
      labels = true;
      $3("#showLabels").checked = true;
      try {
        await selectById(r.id);
      } catch {
        toast("Model yüklenemedi.");
      }
    };
  });
}
